class Solution { public int maxFreq(String s,int maxLetters,int minSize,int maxSize){int[] frequency=new int[26];int left=0,distinct=0,answer=0;Map<String,Integer> counts=new HashMap<>();for(int right=0;right<s.length();right++){if(frequency[s.charAt(right)-'a']++==0)distinct++;if(right-left+1>minSize){if(--frequency[s.charAt(left++)-'a']==0)distinct--;}if(right-left+1==minSize&&distinct<=maxLetters){String value=s.substring(left,right+1);int count=counts.getOrDefault(value,0)+1;counts.put(value,count);answer=Math.max(answer,count);}}return answer;} }
